import{_ as d,o as r,c as a,al as e}from"./chunks/framework.BawR2jEz.js";const p=JSON.parse('{"title":"Фасеты блока","description":"Классификация блоков по функции, отображению, размещению и стилю — зачем нужна, какие измерения бывают и как искать блоки по фасетам.","frontmatter":{"title":"Фасеты блока","description":"Классификация блоков по функции, отображению, размещению и стилю — зачем нужна, какие измерения бывают и как искать блоки по фасетам."},"headers":[],"relativePath":"blocks/facets.md","filePath":"blocks/facets.md"}'),h={name:"blocks/facets.md"};function o(l,t,i,n,b,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="фасеты-блока" tabindex="-1">Фасеты блока <a class="header-anchor" href="#фасеты-блока" aria-label="Permalink to &quot;Фасеты блока&quot;">​</a></h1><p>Фасеты — это классификация блока по нескольким независимым признакам: что блок делает, как выглядит и где на странице стоит. Заполняются в форме блока, используются для поиска в списке.</p><h2 id="зачем" tabindex="-1">Зачем <a class="header-anchor" href="#зачем" aria-label="Permalink to &quot;Зачем&quot;">​</a></h2><p>Когда блоков десяток, их различают по названию. Когда за сотню — уже нет: половина называется «Баннер», «Баннер 2», «Баннер главная». Фасеты дают другой способ найти нужное — не по имени, а по признакам: «мне нужен полноширинный блок со списком товаров для главной».</p><p>Тот же набор признаков помогает понять, что блок вообще делает, не открывая его шаблон.</p><h2 id="как-заполнить" tabindex="-1">Как заполнить <a class="header-anchor" href="#как-заполнить" aria-label="Permalink to &quot;Как заполнить&quot;">​</a></h2><p>Фасеты задаются в форме блока, в разделе настроек. Два измерения обязательны — <strong>Функция</strong> и <strong>Отображение</strong>; остальные заполняются по желанию и могут остаться пустыми.</p><p><strong>Визуальный стиль</strong> допускает несколько значений сразу: блок может быть одновременно тёмным и градиентным. В остальных измерениях выбирается одно значение.</p><h2 id="как-искать" tabindex="-1">Как искать <a class="header-anchor" href="#как-искать" aria-label="Permalink to &quot;Как искать&quot;">​</a></h2><p>В списке блоков фасеты работают фильтром. Выбранные значения сужают список, кнопка <strong>Ещё фильтры</strong> открывает измерения, скрытые за основными. Фильтры складываются: указав функцию «Список сущностей» и размещение «Основной контент», вы получите только блоки, подходящие под оба признака.</p><h2 id="измерения" tabindex="-1">Измерения <a class="header-anchor" href="#измерения" aria-label="Permalink to &quot;Измерения&quot;">​</a></h2><h3 id="функция" tabindex="-1">Функция <a class="header-anchor" href="#функция" aria-label="Permalink to &quot;Функция&quot;">​</a></h3><p>Что блок делает. Обязательное измерение.</p><table tabindex="0"><thead><tr><th>Значение</th><th>Что относится</th></tr></thead><tbody><tr><td>Навигация</td><td>Меню, хлебные крошки, якорные ссылки</td></tr><tr><td>Сбор данных</td><td>Формы обратной связи, подписки, опросы</td></tr><tr><td>Отображение контента</td><td>Текстовые блоки, статьи, FAQ, описания</td></tr><tr><td>Список сущностей</td><td>Подборки товаров, документов, категорий</td></tr><tr><td>Медиа-витрина</td><td>Галереи, слайдеры, видео, баннеры</td></tr><tr><td>Структура макета</td><td>Шапки, подвалы, разделители, сетки</td></tr><tr><td>Социальное доказательство</td><td>Отзывы, рейтинги, логотипы клиентов</td></tr><tr><td>Коммерция</td><td>Корзина, тарифы, карточки товаров</td></tr><tr><td>Коммуникация</td><td>Контакты, чат, мессенджеры, карты</td></tr><tr><td>Утилита</td><td>Кнопка наверх, cookie-баннер, скрипты</td></tr><tr><td>Декорация</td><td>Визуальные эффекты: снег, анимации, фоны</td></tr><tr><td>Поиск</td><td>Поиск по сайту, фильтрация, автодополнение</td></tr><tr><td>Аккаунт пользователя</td><td>Авторизация, личный кабинет, профиль</td></tr><tr><td>Призыв к действию</td><td>Баннеры с кнопкой, акционные блоки</td></tr></tbody></table><h3 id="отображение" tabindex="-1">Отображение <a class="header-anchor" href="#отображение" aria-label="Permalink to &quot;Отображение&quot;">​</a></h3><p>Какую форму блок принимает на странице. Обязательное измерение.</p><table tabindex="0"><thead><tr><th>Значение</th><th>Что означает</th></tr></thead><tbody><tr><td>Секция страницы</td><td>Полноширинная секция в потоке страницы</td></tr><tr><td>Инлайн-блок</td><td>Встраивается внутрь другого контента</td></tr><tr><td>Сайдбар</td><td>Боковая колонка рядом с основным контентом</td></tr><tr><td>Модальное окно</td><td>Всплывающее окно поверх страницы</td></tr><tr><td>Выдвижная панель</td><td>Панель, выезжающая сбоку экрана</td></tr><tr><td>Плавающий</td><td>Свободно позиционированный элемент на странице</td></tr><tr><td>Прилипающий</td><td>Фиксируется при прокрутке</td></tr><tr><td>Выпадающий</td><td>Появляется при клике или наведении</td></tr><tr><td>Полноэкранный</td><td>Занимает весь экран</td></tr><tr><td>Уведомление</td><td>Короткое сообщение, исчезает автоматически</td></tr><tr><td>Полоса</td><td>Узкая горизонтальная полоса: topbar, инфолента</td></tr><tr><td>Карточка</td><td>Компактный контейнер с рамкой или тенью</td></tr><tr><td>Оверлей</td><td>Слой поверх контента с затемнением</td></tr></tbody></table><h3 id="размещение" tabindex="-1">Размещение <a class="header-anchor" href="#размещение" aria-label="Permalink to &quot;Размещение&quot;">​</a></h3><p>Где на странице блок обычно стоит.</p><table tabindex="0"><thead><tr><th>Значение</th><th>Что означает</th></tr></thead><tbody><tr><td>Область шапки</td><td>Верхняя часть страницы, над основным контентом</td></tr><tr><td>Перед контентом</td><td>Между шапкой и основным содержимым</td></tr><tr><td>Основной контент</td><td>Центральная область страницы</td></tr><tr><td>Левый сайдбар</td><td>Боковая колонка слева от контента</td></tr><tr><td>Правый сайдбар</td><td>Боковая колонка справа от контента</td></tr><tr><td>После контента</td><td>Между основным содержимым и подвалом</td></tr><tr><td>Область подвала</td><td>Нижняя часть страницы</td></tr><tr><td>Глобальный оверлей</td><td>Модалка или оверлей вне потока страницы</td></tr><tr><td>Глобальный фиксированный</td><td>Зафиксирован на экране</td></tr><tr><td>Внутри сущности</td><td>Встроен в карточку товара, документа и подобное</td></tr></tbody></table><h3 id="отрасль" tabindex="-1">Отрасль <a class="header-anchor" href="#отрасль" aria-label="Permalink to &quot;Отрасль&quot;">​</a></h3><p>Для какого типа сайта блок задуман.</p><table tabindex="0"><thead><tr><th>Значение</th><th>Что относится</th></tr></thead><tbody><tr><td>Универсальный</td><td>Подходит для любого типа сайта</td></tr><tr><td>Интернет-магазин</td><td>Товары, корзина, каталог, акции</td></tr><tr><td>Лендинг</td><td>Одностраничник с фокусом на конверсию</td></tr><tr><td>Корпоративный</td><td>Компании, услуги, о нас, команда</td></tr><tr><td>Блог</td><td>Статьи, посты, авторские публикации</td></tr><tr><td>Портфолио</td><td>Работы, проекты, кейсы</td></tr><tr><td>SaaS</td><td>Сервисы, тарифы, возможности продукта</td></tr><tr><td>Недвижимость</td><td>Объекты, планировки, каталог жилья</td></tr><tr><td>Медицина</td><td>Клиники, врачи, услуги, запись</td></tr><tr><td>Образование</td><td>Курсы, расписание, преподаватели</td></tr><tr><td>Ресторан</td><td>Меню, бронирование, доставка еды</td></tr><tr><td>Авто</td><td>Автосалоны, сервис, каталог авто</td></tr><tr><td>Путешествия</td><td>Туры, направления, бронирование</td></tr><tr><td>Мероприятия</td><td>Конференции, афиши, расписание</td></tr><tr><td>Некоммерческий</td><td>Благотворительность, миссия, волонтёрство</td></tr></tbody></table><h3 id="визуальныи-стиль" tabindex="-1">Визуальный стиль <a class="header-anchor" href="#визуальныи-стиль" aria-label="Permalink to &quot;Визуальный стиль&quot;">​</a></h3><p>Как блок выглядит. Единственное измерение, где можно выбрать несколько значений.</p><table tabindex="0"><thead><tr><th>Значение</th><th>Что означает</th></tr></thead><tbody><tr><td>Минимализм</td><td>Чистый дизайн, много воздуха, мало декора</td></tr><tr><td>Корпоративный</td><td>Строгий, консервативный, деловой стиль</td></tr><tr><td>Креативный</td><td>Нестандартная вёрстка, яркие акценты</td></tr><tr><td>Тёмный</td><td>Тёмный фон, светлый текст</td></tr><tr><td>Светлый</td><td>Светлый фон, стандартная палитра</td></tr><tr><td>Глассморфизм</td><td>Полупрозрачные карточки с размытием фона</td></tr><tr><td>Брутализм</td><td>Грубые формы, контрастная типографика</td></tr><tr><td>Градиент</td><td>Плавные переходы цветов в фоне и элементах</td></tr><tr><td>Плоский</td><td>Без теней и объёма, чёткие цветовые блоки</td></tr><tr><td>Неоморфизм</td><td>Мягкие тени, эффект выдавленных элементов</td></tr><tr><td>Ретро</td><td>Винтажная палитра, стилизация под старое</td></tr><tr><td>Material</td><td>Карточки, тени, ripple в духе Material Design</td></tr></tbody></table><h3 id="интерактивность" tabindex="-1">Интерактивность <a class="header-anchor" href="#интерактивность" aria-label="Permalink to &quot;Интерактивность&quot;">​</a></h3><p>Сколько в блоке кода и от чего он зависит.</p><table tabindex="0"><thead><tr><th>Значение</th><th>Что означает</th></tr></thead><tbody><tr><td>Статичный</td><td>Без JS — чистый HTML и CSS</td></tr><tr><td>CSS-интерактивный</td><td>Ховеры, transitions, CSS-анимации</td></tr><tr><td>JS лёгкий</td><td>Слайдер, аккордеон, простые скрипты</td></tr><tr><td>JS насыщенный</td><td>Сложная логика, много взаимодействий</td></tr><tr><td>Внешний API</td><td>Подключение к стороннему сервису: карты, чат</td></tr></tbody></table><p>Измерение полезно при разборе производительности: блоки с насыщенным JS и внешними API — первые кандидаты на проверку, когда страница тормозит.</p><h3 id="адаптивность" tabindex="-1">Адаптивность <a class="header-anchor" href="#адаптивность" aria-label="Permalink to &quot;Адаптивность&quot;">​</a></h3><p>Как блок ведёт себя на разных экранах.</p><table tabindex="0"><thead><tr><th>Значение</th><th>Что означает</th></tr></thead><tbody><tr><td>Адаптивный</td><td>Корректно отображается на всех устройствах</td></tr><tr><td>Только десктоп</td><td>Работает только на больших экранах</td></tr><tr><td>Только мобильный</td><td>Отображается только на телефонах</td></tr><tr><td>Адаптивный (breakpoints)</td><td>Разные макеты для разных разрешений</td></tr></tbody></table><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./">Блоки</a> — создание и редактирование блоков</li><li><a href="./twig-methods.html">Контекстные методы блока</a> — что доступно в шаблоне блока</li></ul>',35)])])}const u=d(h,[["render",o]]);export{p as __pageData,u as default};
